import{_ as o,l as i,o as e,c as s,v as t,p as n,x as l,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"稳定婚姻算法","description":"","frontmatter":{"title":"稳定婚姻算法","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/stable-marriage-algo.md","filePath":"cs/stable-marriage-algo.md","lastUpdated":1789023840000}'),c={name:"cs/stable-marriage-algo.md"};function m(_,a,u,E,A,S){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="稳定婚姻算法" tabindex="-1">稳定婚姻算法 <a class="header-anchor" href="#稳定婚姻算法" aria-label="Permalink to &quot;稳定婚姻算法&quot;">​</a></h1><div class="epigraph"><p>双方提交全序偏好；Gale–Shapley 求婚直到没有人被拒绝得动：结果稳定，且提出方最优。</p><footer>—— 据 Gale and Shapley, College Admissions and the Stability of Marriage, 1962；Knuth, Stable Marriage and Its Relation to Other Combinatorial Problems, 1976 整理</footer></div><p>上一课<a href="/cs/blossom-matching">Edmonds 带花树</a>求一般图最大基数匹配。本课匹配仍是一对一，但目标换成<strong>稳定</strong>：没有阻塞对 \\((m,w)\\) 使得二人都更喜欢对方而非当前配偶。不重写花。缺口是 Gale–Shapley 的求婚过程。后课图着色，离开匹配。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>二分（男–女，或申请人–学校一席）。偏好严格全序。匹配稳定：不存在互相更偏好的未匹配对。稳定匹配一定存在。Gale–Shapley：一方求婚，另一方暂持当前最好、可悔。未匹配求婚者向尚未拒绝他的名单下一人求婚。终止时稳定。</p><p>提出方最优：每个提出者得到所有稳定匹配中自己能得到的最好对象；接受方最差。缺口是稳定性，不是权和最大（那是 KM）。</p><h3 id="不是最大匹配" tabindex="-1">不是最大匹配 <a class="header-anchor" href="#不是最大匹配" aria-label="Permalink to &quot;不是最大匹配&quot;">​</a></h3><p>基数在完全偏好下自然完美（双方人数相等）。不稳定的完美匹配很多。医院–居民有容量时是 HR 问题，GS 可推广；本课先一对一。</p><p><span class="marginnote">Gale–Shapley 1962。Knuth 1976 讲义把变体与循环讲清。Roth–Sotomayor 是经济学侧，本课算法：终止、稳定、最优侧。后课着色是另一组合标签。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每人列表指针。循环：取一个自由求婚者，向列表下一人求婚；对方若更偏好则甩掉旧的。\\(O(n^2)\\) 次求婚（每人每条偏好至多一次）。</p>',11)),(e(),n(p,null,{default:l(()=>[h(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E8%87%AA%E7%94%B1%E6%B1%82%E5%A9%9A%E8%80%85%22%5D%20--%3E%20ASK%5B%22%E5%90%91%E5%90%8D%E5%8D%95%E4%B8%8B%E4%B8%80%E4%BA%BA%E6%B1%82%E5%A9%9A%22%5D%0A%20%20ASK%20--%3E%20HOLD%5B%22%E5%AF%B9%E6%96%B9%E6%9A%82%E6%8C%81%E6%9B%B4%E5%A5%BD%E8%80%85%22%5D%0A%20%20HOLD%20--%3E%20P%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>平局偏好要事先破，否则稳定定义要改弱。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>不变式：被拒绝的人以后不会被该接受方接受（接受方偏好只升不降）。终止后若有阻塞对，可推出某次求婚应被接受而未发生，矛盾。提出方最优：任何稳定匹配里，提出者都不会得到比 GS 更好的对象——否则最早被「更好」拒绝的时刻可造阻塞。</p><p>与带花：那里没有偏好，只有边在不在。本课边都在，质量来自序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写宿舍问题（非二分稳定匹配可能空）、不写策略操纵全文。不把匹配市场当金融课。后课默认：稳定婚姻 = GS；\\(O(n^2)\\)；提出方最优。下一课图着色与贪心启发。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>稳定 = 无阻塞对；GS 求婚保证存在。</li><li>提出方最优、接受方最差。</li><li>目标不是最大权或最大基数本身。</li><li>出处：Gale and Shapley, 1962；Knuth, 1976。</li></ul>',8))])}const g=o(c,[["render",m]]);export{f as __pageData,g as default};
